// Edit protocol/messages.json and run `pnpm gen`.

/** EntityFlags bits. */
export const EntityFlags = {
  crouching: 1,
  sliding: 2,
  climbing: 4,
  dashing: 8,
  onGround: 16,
  mantling: 32,
} as const;

/** One client command for one tick. jump and dash are "pressed this tick" edges; the rest are held states. */
export interface Input {
  /** Sequence number, 1-based, one per client sim tick. */
  seq: number;
  /** Strafe, -1 (left) to +1 (right). */
  moveX: number;
  /** Forward, -1 (back) to +1 (forward). */
  moveZ: number;
  /** Look direction in radians. Yaw 0 faces -Z; positive yaw turns left. */
  yaw: number;
  /** Look pitch in radians; positive looks up. Not used by movement. */
  pitch: number;
  jump: boolean;
  /** Jump button held (climbing). */
  jumpHeld: boolean;
  dash: boolean;
  /** Crouch/slide key held. */
  slide: boolean;
  /** Aiming down sights (held): slows ground movement. */
  ads: boolean;
}

/** Complete movement state. (x, y, z) is the centre of the player's feet. Metres and seconds, Y up. */
export interface PlayerState {
  x: number;
  y: number;
  z: number;
  vx: number;
  vy: number;
  vz: number;
  onGround: boolean;
  climbing: boolean;
  /** Crouched (hold the slide key without enough speed to slide). */
  crouching: boolean;
  sliding: boolean;
  slideTime: number;
  slideCooldown: number;
  /** Fractional: regenerates continuously up to the maximum. */
  dashCharges: number;
  /** Seconds of dash remaining; 0 when not dashing. */
  dashTime: number;
  dashDirX: number;
  dashDirZ: number;
  /** Air jumps left; refilled whenever grounded. */
  airJumps: number;
  coyote: number;
  jumpBuffer: number;
  mantling: boolean;
  mantleT: number;
  mantleFromX: number;
  mantleFromY: number;
  mantleFromZ: number;
  mantleToX: number;
  mantleToY: number;
  mantleToZ: number;
}

/** What other players need to draw and interpolate someone. Every entity carries a teamId. */
export interface Entity {
  id: number;
  teamId: number;
  x: number;
  y: number;
  z: number;
  yaw: number;
  pitch: number;
  /** Bit set of EntityFlags. */
  flags: number;
}

/** The latest few inputs, oldest first. Resent redundantly so a lost message does not lose inputs; the server skips sequence numbers it already has. */
export interface InputMessage {
  type: "input";
  inputs: Input[];
}

/** Round-trip and clock probe. */
export interface PingMessage {
  type: "ping";
  /** Client time in ms, echoed back in pong. */
  t: number;
}

/** Ask the server to put this player back at a spawn point. */
export interface RespawnMessage {
  type: "respawn";
}

/** Sent once on connect. */
export interface WelcomeMessage {
  type: "welcome";
  playerId: number;
  tickRate: number;
  snapshotRate: number;
  /** Level the server runs, for example greybox. */
  level: string;
}

/** The world as this player may see it, 30 times a second. */
export interface SnapshotMessage {
  type: "snapshot";
  /** Server tick this snapshot describes. */
  tick: number;
  /** Last input sequence the server has simulated for you. `you` is your state right after it. */
  ackSeq: number;
  /** Inputs of yours still waiting on the server (a measure of how far ahead you are). */
  queued: number;
  you: PlayerState;
  /** Everyone else you can see (see entitiesFor). */
  entities: Entity[];
}

/** Reply to ping. */
export interface PongMessage {
  type: "pong";
  /** The client time from the ping. */
  t: number;
  /** Server tick when the ping was handled. */
  tick: number;
}

export type ClientMessage =
  | InputMessage
  | PingMessage
  | RespawnMessage;

export type ServerMessage =
  | WelcomeMessage
  | SnapshotMessage
  | PongMessage;

const SERVER_TYPES = new Set<string>(["welcome","snapshot","pong"]);

/** Parse a server message. Returns null for anything that is not a known message. */
export function parseServerMessage(text: string): ServerMessage | null {
  const msg = JSON.parse(text) as { type?: unknown };
  return typeof msg.type === "string" && SERVER_TYPES.has(msg.type) ? (msg as ServerMessage) : null;
}
